function values = rfdude_pll_sweep_values(type, list_text, start_text, stop_text, step_text, points_text)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Resolve GUI sweep inputs to the existing runner's numeric sweep_values.
switch type
    case 'List'
        values=rfdude_pll_parse_value(list_text);
    case {'Start / stop / step','Log (points per octave)'}
        first=scalar_value(start_text,'Sweep start');
        last=scalar_value(stop_text,'Sweep stop');
        if strcmp(type,'Start / stop / step')
            step=scalar_value(step_text,'Sweep step');
            if step==0 || (last~=first && sign(step)~=sign(last-first))
                error('Sweep step must be nonzero and point toward the stop');
            end
            count=(last-first)/step;
            if ~isfinite(count) || count>=100000
                error('Numeric vectors are limited to 100000 entries');
            end
            values=first:step:last;
        else
            points=scalar_value(points_text,'Points per octave');
            if first<=0 || last<=0
                error('Log sweep start and stop must be positive');
            end
            if points<1 || points~=fix(points)
                error('Points per octave must be a positive integer');
            end
            span=abs(log2(last)-log2(first))*points;
            if ~isfinite(span) || span>99999
                error('Numeric vectors are limited to 100000 entries');
            end
            tolerance=8*eps(max(1,span));
            intervals=floor(span+tolerance);
            direction=sign(last-first);
            values=2.^(log2(first)+direction*(0:intervals)/points);
            values(1)=first;
            % Include the exact stop, even when it needs a shorter final interval.
            if first==last || (intervals>0 && abs(span-intervals)<=tolerance)
                values(end)=last;
            else
                values(end+1)=last;
            end
        end
    otherwise
        error('Unsupported sweep type: %s',type);
end
validateattributes(values,{'numeric'},{'vector','real','finite','nonempty'},'','sweep values');
if numel(values)>100000
    error('Numeric vectors are limited to 100000 entries');
end
if numel(unique(values))~=numel(values)
    error('Sweep values must be distinct; increase the spacing');
end
end

function value=scalar_value(text,label)
value=rfdude_pll_parse_value(text);
validateattributes(value,{'numeric'},{'scalar','real','finite'},'',label);
end
